const input = $input.first().json;
const caption = input.caption;
const files = input.media_file;

// Agar files nahi hain to empty array return karo
if (!files || files.length === 0) {
  return [];
}

// Har file ko alag item banake usme caption add karo
const result = files.map(file => ({
  // File ki saari properties
  filename: file.filename,
  mimetype: file.mimetype,
  size: file.size,

  // Form ke saari fields
  caption: caption,
  post_time: input.post_time,
  Date: input.Date,
  Tags: input.Tags,
  submittedAt: input.submittedAt,

  // Binary data ka reference
  binaryData: {
    fileName: file.filename,
    mimeType: file.mimetype,
    data: `={{$binary.media_file[${files.indexOf(file)}]}}`  // Important!
  }
}));

return result;

// Code Node: Message Platform Selector
const platforms = $json.platform_selection|| [];
const caption = $json.caption || "";

// Message-only ke liye valid platforms
// Instagram ko hatao kyunki text-only post nahi hota
const VALID_TEXT_PLATFORMS = ["linkedin", "facebook", "threads", "mastodon", "tumblr"];

let targetPlatforms = [];

if (platforms.length === 0) {
    // Koi select nahi → sab valid text platforms
    targetPlatforms = VALID_TEXT_PLATFORMS;
    console.log("No platforms selected → Posting message to ALL text platforms");
} else {
    // User ne jo select kiye, unme se sirf valid text platforms lo
    targetPlatforms = platforms
        .map(p => {
            let plat = p.toLowerCase().trim();
            if (plat === "linkdin") plat = "linkedin";
            return plat;
        })
        .filter(p => VALID_TEXT_PLATFORMS.includes(p)); // Sirf valid text platforms

    console.log(`Selected platforms: ${targetPlatforms.join(", ")}`);
}

// Agar koi platform valid nahi bacha to default do
if (targetPlatforms.length === 0) {
    targetPlatforms = ["linkedin"]; //至少 LinkedIn pe to bhejo
    console.log("No valid text platforms → Defaulting to LinkedIn");
}

return {
    ...$json,
    targetPlatforms: targetPlatforms,
    platformCount: targetPlatforms.length,
    message: caption,
    isMessageOnly: true
};

