const item = $input.first();
const binary = item.binary;

const formData = {
  type: "photo",
  caption: item.json.caption
};

let index = 0;

for (const key of Object.keys(binary)) {
  formData[`data[${index}]`] = {
    value: binary[key],
    options: {
      filename: binary[key].fileName,
      contentType: binary[key].mimeType
    }
  };
  index++;
}

return [{
  json: {
    body: formData
  }
}];

const blog = "YOUR_BLOG.tumblr.com";

// OAuth2 credential access
const token = $credentials["Unnamed credential 3"].access_token;

const form = new FormData();

form.append("type", "photo");
form.append("caption", $json.caption || "");

let index = 0;

// Loop through all binary images
for (const key of Object.keys($binary)) {

  const fileBuffer = Buffer.from($binary[key].data, "base64");

  form.append(`data[${index}]`, fileBuffer, {
    filename: $binary[key].fileName,
    contentType: $binary[key].mimeType
  });

  index++;
}

// Send request to Tumblr
const response = await this.helpers.httpRequest({
  method: "POST",
  url: `https://api.tumblr.com/v2/blog/${blog}/post`,
  headers: {
    Authorization: `Bearer ${token}`
  },
  body: form
});

return [{ json: response }];

